/** 코스튬 목록은 API로만 읽음. 잠긴 복장도 미리보기 가능하며 저장은 unlocks.setCostume만 사용. */
export function createCostumePicker(box, o){ensureMetaStyle();let car=null,shown='',generation=0;const keyFor=(id)=>'costume:'+id;
 function owned(id){return !id||meta.owns(keyFor(id))||unlocks.getCostume(car.id)===id;}
 function options(){return listCostumes(car.id);}
 function painted(){return unlocks.applyPaint(car.look0||car.look,car.id);}
 function preview(id){shown=id;o.onPreview(applyCostume(painted(),id));render(false);
  const selected=[...box.querySelectorAll('[data-costume-preview]')].find(b=>b.dataset.costumePreview===id);
  selected?.focus({preventScroll:true});
  // 낮은 화면에서도 고른 디자인 설명·구매 조건이 바로 보이게, 내부 패널만 이동.
  const detail=box.querySelector('.mt-costume-detail');
  let scroller=box.parentElement;
  while(scroller&&!/^(auto|scroll)$/.test(getComputedStyle(scroller).overflowY))scroller=scroller.parentElement;
  if(detail&&scroller){const r=detail.getBoundingClientRect(),s=scroller.getBoundingClientRect();const foot=scroller.querySelector('.h-carinfo .btns, :scope > .btns');const footPos=foot&&getComputedStyle(foot).position;const bottom=foot&&['sticky','fixed'].includes(footPos)?Math.min(s.bottom,foot.getBoundingClientRect().top)-12:s.bottom-12;if(r.bottom>bottom)scroller.scrollTop+=r.bottom-bottom;else if(r.top<s.top+12)scroller.scrollTop+=r.top-s.top-12;}
 }
 function render(photos=true){if(!car)return;const all=options(),equipped=unlocks.getCostume(car.id);box.innerHTML='<div class="mt-costume-head"><b>✦ 차량 코스튬'+'</b><span title="커스텀 조각 · 색·코스튬·세리머니">'+money('custom',meta.balance('custom'))+'</span></div>'+(all.length?'<small class="mt-costume-note">디자인을 눌러 미리 보세요 · 레벨이 되면 커스텀 조각으로 사요 · 성능은 그대로</small><div class="mt-costumes">'+[{id:'',name:'기본 복장',unlockLevel:0},...all].map(c=>{const key=car.id+'@'+(c.id||'default'),url=thumbUrl(key),open=!c.id||unlocks.isCostumeUnlocked(car.id,c.id);return '<button data-nav class="mt-costume '+(shown===c.id?'on':'')+'" data-coach="garage.costume" data-costume-preview="'+c.id+'" aria-pressed="'+(shown===c.id)+'"><span class="mt-costume-pic">'+(url?'<img src="'+url+'" alt="">':'<span>🏎️</span>')+(equipped===c.id?'<i>✓ 착용</i>':'')+'</span><b>'+esc(c.name)+'</b><small>'+(!c.id?'언제나 자유롭게':owned(c.id)?'보유 중 · '+(open?'착용 가능':'Lv.'+c.unlockLevel+' 착용'):(!open?'🔒 Lv.'+c.unlockLevel+' · ':'Lv.'+c.unlockLevel+' · ')+currencyIcon('custom',12)+' '+costumePrice(c))+'</small></button>';}).join('')+'</div><div class="mt-costume-detail"></div>':'<div class="mt-costume-empty"><b>이 차의 매력은 기본 복장에!</b><p>이 차의 전용 코스튬은 준비 중이에요. 지금은 색 바꾸기로 내 스타일을 만들어 보세요.</p></div>');
 const detail=box.querySelector('.mt-costume-detail');const selected=all.find(c=>c.id===shown);if(detail){const open=!selected||unlocks.isCostumeUnlocked(car.id,shown);detail.innerHTML='<b>'+esc(selected?.name||'기본 복장')+'</b><p>'+esc(selected?.desc||'원래 차 디자인과 내가 고른 페인트로 돌아가요.')+'</p><div><small>'+(!selected?'무료':!open?'Lv.'+selected.unlockLevel+'부터 구매·착용 · 완주·목표로 XP를 모아요':owned(shown)?'내 컬렉션':money('custom',costumePrice(selected))+(meta.balance('custom')<costumePrice(selected)?' · '+shortHtml({kind:'costume',missing:costumePrice(selected)-meta.balance('custom')}):' · 사면 영구 보유'))+'</small><button data-nav class="gm-btn '+(open?'primary':'')+'" data-costume-equip '+(!open?'disabled':'')+'>'+(!open?'🔒 Lv.'+selected.unlockLevel:equipped===shown?'✓ 착용 중':owned(shown)?'이 복장 입기':'구매하고 입기')+'</button></div>'+(shown!==equipped?'<button data-nav class="mt-preview-reset" data-costume-reset>미리보기 끝내기 · 착용한 모습으로</button>':'');}
 if(photos&&all.length){const token=++generation;const variants=[{id:'',name:'기본 복장'},...all].map(c=>({...car,id:car.id+'@'+(c.id||'default'),look:applyCostume(painted(),c.id)}));loadCarThumbs(variants,{channel:'costume-preview',first:car.id+'@'+(shown||'default'),onThumb:(id,url)=>{if(token!==generation)return;const index=variants.findIndex(v=>v.id===id);const btn=box.querySelectorAll('[data-costume-preview]')[index];const pic=btn?.querySelector('.mt-costume-pic');if(!pic)return;let im=pic.querySelector('img');if(!im){pic.querySelector('span')?.remove();im=new Image();im.alt='';pic.prepend(im);}im.src=url;}});}}
 box.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-costume-preview'))preview(b.dataset.costumePreview);else if(b.hasAttribute('data-costume-reset'))preview(unlocks.getCostume(car.id));else if(b.hasAttribute('data-costume-equip')){const c=options().find(c=>c.id===shown);if(c&&!owned(shown)){const it={...c,kind:'costume',currency:'custom',price:costumePrice(c),carName:car.name,missing:Math.max(0,costumePrice(c)-meta.balance('custom'))};if(it.missing>0)return o.toast(shortText(it));if(!await buyDialog(it,{art:thumbUrl(car.id+'@'+c.id),note:'사서 바로 입어요 · 성능은 그대로'}))return;const r=meta.buy('costume',c);if(!r.ok)return o.toast(r.message);}if(!unlocks.setCostume(car.id,shown))return o.toast('아직 이 코스튬을 입을 수 없어요.');o.onEquipped(applyCostume(painted(),shown));render(false);uiSound('select');o.toast('✦ '+(c?.name||'기본 복장')+' 착용!');}});
 return {show(c){generation++;car=c;shown=unlocks.getCostume(c.id);render();},restore(){if(car&&shown!==unlocks.getCostume(car.id)){shown=unlocks.getCostume(car.id);o.onPreview(applyCostume(painted(),shown));}},refresh(){render(false);}};
}
/** 결과 화면 '보상 내역' 줄들 (summary lines → 이유 + 세 조각). 예전 summary면 피트만 */
export function linesHtml(r){const lines=Array.isArray(r?.lines)&&r.lines.length?r.lines:[{reason:'완주',pit:r?.base||0},{reason:'순위',pit:r?.place||0},{reason:'업적·목표',pit:Math.max(0,(r?.coins||0)-(r?.base||0)-(r?.place||0))}].filter(l=>l.pit>0);return lines.map(l=>'<div class="mt-line"><span>'+esc(l.reason)+'</span><span class="mt-cur-row">'+rewardChipsHtml(l,{size:13})+'</span></div>').join('');}
export function metaResultsHtml(r) {
  if (!r) return '';
  const p = r.profile;
  const achieved = r.achievements.map(id => ACHIEVEMENTS.find(a => a.id === id)).filter(Boolean).sort((a,b) => b.tier-a.tier);
  const row = a => '<span>' + ['','🥉','🥈','🥇'][a.tier] + ' ' + esc(a.name) + ' ' + rewardChipsHtml(a.reward||{pit:a.coins},{size:13}) + '</span>';
  const next = p ? nextUnlock(p.level) : null;
  const newParts=partsBetween(r.beforeLevel||p?.level||1,p?.level||1),gifts=takeNews();
  const partReward=(newParts.length||gifts.length)?'<div class="mt-result-ach">'+newParts.map(x=>'<span>🔧 '+esc(x.name)+' · '+(rewardLockText({kind:'part',how:'coin'})||'구매 가능')+'</span>').join('')+gifts.map(x=>'<span>🎁 '+esc(x.name)+'</span>').join('')+(isOpen('parts')?'<a class="mt-result-link" href="?menu=car&carTab=parts">차고에서 끼우기 →</a>':'<span>🔒 Lv.'+levelOf('parts')+'에 열려요</span>')+'</div>':'';
  const xp = (r.xp || 0) + (r.raceXp || 0);
  return '<section class="mt-result">' + (p ? '<div class="res-xp"><div><b>Lv.' + p.level + '</b><span>' + esc(p.title) + (p.level > r.beforeLevel ? ' · 레벨 업!' : '') + '</span><strong>+' + n(xp) + ' XP</strong></div><div class="res-xp-bar" role="progressbar" aria-label="다음 레벨 경험치" aria-valuemin="0" aria-valuemax="' + p.need + '" aria-valuenow="' + Math.min(p.have,p.need) + '"><i style="width:' + Math.round(p.pct*100) + '%"></i></div><small>' + (p.level >= 99 ? '최고 레벨' : n(p.have) + ' / ' + n(p.need) + ' XP · 다음 레벨까지 ' + n(Math.max(0,p.need-p.have))) + '</small></div>' : '') +
    partReward + '<div class="mt-result-top cur-gain"><div><small>이번 판 조각</small><span class="mt-cur-row">' + (rewardChipsHtml(r.gain||{pit:r.coins},{size:20})||'<b class="mt-none">없음</b>') + '</span></div><div class="mt-result-balance"><small>보유</small>' + walletChipsHtml(r.wallet||{pit:r.balance,up:0,custom:0},{size:14}) + '</div></div>' +
    (achieved.length ? '<div class="mt-result-ach">' + achieved.slice(0,2).map(row).join('') + '</div>' : '') +
    '<div class="res-next-goal"><small>다음 목표</small><b>' + (next ? 'Lv.' + next.level + ' · ' + esc(next.text) : r.progress[0] ? esc(r.progress[0].name) : '다음 레이스에 도전해요') + '</b>' + (!next && r.progress[0] ? '<small>' + amount(r.progress[0].value,r.progress[0].unit) + ' / ' + amount(r.progress[0].goal,r.progress[0].unit) + '</small>' : '') + '</div>' +
    '<details class="res-detail"><summary>보상 자세히' + (achieved.length ? ' · 업적 ' + achieved.length + '개 달성' : '') + '</summary><div class="res-reward-details"><div class="mt-result-breakdown">' + linesHtml(r) + '완주 +' + (r.raceXp||0) + ' · 업적·목표 +' + (r.xp||0) + ' XP</div>' + (r.title ? '<div class="mt-result-title">✦ ' + esc(r.title) + '</div>' : '') + '<div class="mt-result-ach">' + achieved.slice(2).map(row).join('') + '</div>' + (r.goals.length ? '<p class="mt-result-goals">✓ ' + r.goals.map(g=>esc(g.name)).join(' · ') + '</p>' : '') + r.progress.map(a=>'<div class="mt-result-progress"><span>'+esc(a.name)+'</span><small>'+amount(a.value,a.unit)+' / '+amount(a.goal,a.unit)+'</small>'+bar(a.value,a.goal,a.name)+'</div>').join('') + '</div></details>' + (isOpen('goals') ? '<a class="mt-result-link" href="?menu=achievements">업적 · 목표 →</a>' : '<span class="mt-result-link">🔒 Lv.' + levelOf('goals') + '에 열려요</span>') + '</section>';
}
export function playMetaCelebration(box,c){if(!box||!c||c.id==='stock')return;ensureMetaStyle();box.style.setProperty('--meta-finish',c.colors[0]);box.classList.add('mt-custom-finish');const old=box.querySelector('.mt-finish-art');if(old)old.remove();const wrap=document.createElement('div');wrap.className='mt-finish-art '+c.id;wrap.setAttribute('aria-hidden','true');wrap.innerHTML='<div class="mt-finish-ring"></div>'+Array.from({length:24},(_,i)=>'<i style="--x:'+(i*37%100)+'%;--delay:'+(i%6*.19)+'s;--spin:'+(i*31)+'deg;background:'+c.colors[i%c.colors.length]+'"></i>').join('');box.prepend(wrap);setTimeout(()=>wrap.remove(),6500);}
